  if(name==='type-add'){dialog('新建类型','<label class="field"><span>TypeId / 英文业务键</span><input name="id" required pattern="[A-Za-z_][A-Za-z_0-9]*" value="NewType"></label><label class="field"><span>显示名称</span><input name="label" value="新类型" required></label>',f=>mutate('新建类型',p=>{const id=formString(f,'id');if(p.layout.types.some(t=>t.type_id.toLowerCase()===id.toLowerCase()))throw Error('TypeId已经存在。');p.layout.types.push({type_id:id,asset_path:`/Game/GuLiStrike/Editor/MapAuthoring/Types/DA_${id}.DA_${id}`,display_name:formString(f,'label'),editor_icon:'Icons.Location',color_rgb:[.1,.5,.6],color_alpha:.2,allowed_shapes:['Cylinder','Sphere','Box','PolygonPrism'],fields:[],default_regions:[]});selectedType=id;tab='types';selectedRegion='';}));return;}
  if(name==='field-add'){mutate('新增字段',()=>{const t=kind();if(!t)return;let key='Field1',i=1;while(t.fields.some(f=>f.field_key===key))key='Field'+(++i);t.fields.push({field_id:guid(),field_key:key,display_name:'新字段',field_type:'double',default:0,value_type_object:'',required:false});});return;}
