  if(name==='type-color'){mutate('修改类型预览色',()=>{const t=kind();if(!t)return;const hex=node.dataset.color!;t.color_rgb=[1,3,5].map(i=>{const s=parseInt(hex.slice(i,i+2),16)/255;return s<=.04045?s/12.92:((s+.055)/1.055)**2.4;}) as Vec3;});return;}
