$<HTMLInputElement>('file-input').addEventListener('change',async event=>{const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(dirty)await save(true);await load(await api('/api/import','POST',file));}catch(e){toast((e as Error).message,true);}finally{input.value='';}});

