      const region=pickRegion(wx,wy);if(region){selected=region.m.marker_id;selectedRegion=region.r.region_id;gesture={kind:'region',before:clone(project),start:[wx,wy],last:[wx,wy],id:selected,regionId:selectedRegion};renderAll(false);return;}
