function finishGesture(){if(!gesture)return;const g=gesture;gesture=null;if(g.kind==='selection'){renderSidebar();return;}if(g.before&&g.kind!=='pan'){
  if(g.kind==='vertex'){const r=marker()?.regions.find(r=>r.region_id===g.regionId),error=r?.geometry.vertices?polygonError(r.geometry.vertices):null;if(error){project=g.before;renderAll();toast(error+' 已恢复拖动前的轮廓。',true);return;}}
  if(g.stroke instanceof DensityStroke)g.stroke.finish();changed(g.kind==='terrain'?'绘制地形':g.kind==='density'?'涂绘资源':g.kind==='marker'?'移动据点':g.kind==='region'?'移动区域':'拖动多边形顶点',g.before);}}
view.canvas.addEventListener('pointerup',()=>finishGesture());view.canvas.addEventListener('pointercancel',()=>cancelGesture());view.canvas.addEventListener('lostpointercapture',()=>{if(gesture)cancelGesture();});view.canvas.addEventListener('pointerleave',()=>{if(!gesture){view.mouse=null;view.draw();}});
view.canvas.addEventListener('wheel',event=>{event.preventDefault();const [wx,wy]=view.eventWorld(event),r=view.canvas.getBoundingClientRect();view.zoom=Math.max(.000005,Math.min(5,view.zoom*Math.exp(-event.deltaY*.001)));view.panX=event.clientX-r.left-r.width/2-wx*view.zoom;view.panY=event.clientY-r.top-r.height/2+wy*view.zoom;view.draw();},{passive:false});
document.addEventListener('keydown',event=>{const editing=(event.target as HTMLElement).matches('input,textarea,select,[contenteditable="true"]');if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();if(project)void save().catch(e=>toast(e.message,true));return;}if(editing||document.querySelector('dialog[open]'))return;
  if(event.code==='Space'){event.preventDefault();space=true;}if(event.key==='Escape'){cancelGesture();if(mode==='polygon')mode='select';renderAll(false);}
  if((event.ctrlKey||event.metaKey)&&['z','y'].includes(event.key.toLowerCase())){event.preventDefault();void action(event.key.toLowerCase()==='y'||event.shiftKey?'redo':'undo',document.body).catch(e=>toast(e.message,true));}
  if(event.key.toLowerCase()==='f')focusSelected();if(event.key==='['||event.key===']'){brush().size=Math.max(1,brush().size+(event.key===']'?1:-1));renderSidebar();refresh(false,false);}
  if(event.key==='Enter'&&mode==='polygon'&&project){try{if(draft.length<3)throw Error('至少需要三个顶点。');mutate('绘制多边形',()=>{const m=marker(),r=m?.regions.find(r=>r.region_id===selectedRegion);if(!m||!r)throw Error('请选择多边形区域。');const center=worldPoint(m,r,[0,0,0]);r.geometry.vertices=draft.map(([x,y])=>{const a=inverseRotate([x-m.world_transform.position[0],y-m.world_transform.position[1],center[2]-m.world_transform.position[2]],m.world_transform.rotation_pitch_yaw_roll);const b=inverseRotate(a.map((v,i)=>v-r.relative_transform.position[i]) as Vec3,r.relative_transform.rotation_pitch_yaw_roll);return[b[0],b[1]];});const error=polygonError(r.geometry.vertices!);if(error)throw Error(error);});draft=[];view.draft=[];mode='select';renderAll(false);}catch(e){toast((e as Error).message,true);}}
  if((event.key==='Insert'||event.key==='Delete')&&selectedRegion&&selectedVertex>=0){event.preventDefault();void action(event.key==='Insert'?'polygon-insert':'polygon-remove',document.body).catch(e=>toast(e.message,true));}
});
document.addEventListener('keyup',event=>{if(event.code==='Space')space=false;});window.addEventListener('blur',()=>{space=false;if(gesture)cancelGesture();});
