async function start(){renderAll(false);try{const data=await api('/api/projects');if(data.projects.length)await load(await api('/api/projects/'+data.projects[0].id));else{$('map').insertAdjacentHTML('beforeend','<div class="empty" id="welcome"><div class="big">▦</div><h2>从一张网格开始</h2><p>按3米单位塑造地形，规划据点与资源。<br>在同一份数据上完成二维编辑和三维预览。</p><button class="primary" data-action="snapshots">载入当前地图快照</button><button class="ghost" data-action="new">或新建空白地图</button></div>');}}catch(e){toast('无法读取本地工程：'+(e as Error).message,true);}}
void start();
